3	const [op,narg]=process.argv.slice(2),n=Number(narg);assert.ok(n>=78&&n<=92);
4	function delta(a,z,p=''){if(JSON.stringify(a)===JSON.stringify(z))return [];if(a&&z&&typeof a==='object'&&typeof z==='object'&&!Array.isArray(a)&&!Array.isArray(z))return [...new Set([...Object.keys(a),...Object.keys(z)])].flatMap(k=>delta(a[k],z[k],p+'/'+k));if(Array.isArray(a)&&Array.isArray(z)&&a.every((x,i)=>JSON.stringify(x)===JSON.stringify(z[i])))return [{path:p,append_from:a.length,append:z.slice(a.length)}];if(typeof a==='string'&&typeof z==='string'){let lo=0,hi=0;while(lo<a.length&&lo<z.length&&a[lo]===z[lo])lo++;while(hi<a.length-lo&&hi<z.length-lo&&a[a.length-hi-1]===z[z.length-hi-1])hi++;return [{path:p,before_changed:a.slice(lo,a.length-hi),after_changed:z.slice(lo,z.length-hi),prefix_context:a.slice(Math.max(0,lo-50),lo),suffix_context:hi?a.slice(a.length-hi,a.length-hi+50):''}];}return [{path:p,before:a,after:z}];}
5	function preserve(){assert.equal(sha(fs.readFileSync(path.join(s.project,'.writer/state.json'))),sha(fs.readFileSync(path.join(s.stage,'root-before-state.bin'))));const inv=readJSON(path.join(s.stage,'before-inventory.json'));for(const side of ['root','branch'])for(const x of inv[side])assert.equal(sha(fs.readFileSync(path.join(side==='root'?s.project:b.project,x.file))),x.sha256);}
