9	 const t=b.run('replay-input-'+n,['revision','replay-input','--unit',String(n)]);s.write('replay-template-'+n+'.json',t.value);
10	 const old=baseline.units.find(u=>u.unit===n),bytes=fs.readFileSync(path.join(s.project,old.journal));assert.equal(sha(bytes),old.journal_sha256);const j=JSON.parse(bytes),exact=j.patch.flatMap(p=>delta(p.before,p.after,p.at.join('/')));
11	 s.write('inspect-'+n+'.txt',['unit '+n,'summary '+t.value.summary,'timeline '+JSON.stringify(t.value.changes.timeline_append),'original journal '+old.journal+' SHA '+sha(bytes),...exact.map(x=>JSON.stringify(x)),'replay全部证据 '+JSON.stringify(Object.fromEntries(Object.entries(t.value.changes.ledger||{}).map(([id,x])=>[id,x.evidence]))),'replay角色 '+JSON.stringify(t.value.changes.characters),'当前顾 '+b.state().snapshot.characters['顾遥'],'context plan '+JSON.stringify(c.value.plan),'source_hashes '+JSON.stringify(t.value.source_hashes),'context keys '+Object.keys(c.value).join(','),'omitted '+JSON.stringify(c.value.continuity?.recall?.omitted_ids)].join('\n')+'\n');
